(function(root){
'use strict';
const fields=[['B','Bの最低人数',0],['C','Cの最低人数',0],['D','Dの最低人数',0],['maxRun','連続勤務の上限',1],['off','休日の目安',0]];
function settings(r){return fields.map(([key,label])=>label+'：'+r[key]+(['maxRun','off'].includes(key)?'日':'人')).join('\n');}
function template(r){return '【自動反映する設定】\n'+settings(r)+'\n'+"\n【基本方針・現在の自動作成】\n・希望休「希」はE（休日）、有給希望「有」はF（有休）として確保する。\n・手直しして固定したセルは再作成でも保持する。希望と固定勤務が矛盾するときは作成を止める。\n・職員の入職日・最終勤務日、勤務可能曜日、夜勤可否、夜勤上限を使う。\n・D（夜勤入り）→翌日d（明け）→翌々日E（休日）を基本とする。希望・固定と両立しない場合は警告を確認する。\n・前月の作成データがあれば前月最終日の勤務を参照し、なければ手入力の前月末勤務を使う。\n・前月末Dの場合は1日d・2日E、前月末dの場合は1日Eを確保する。\n・日別に指定したB・C・Dの必要人数は、月の最低人数より優先する。\n・勤務時間の目安は「今月の個別設定」→「職員の月間時間」→「（月の日数−休日目安）×8」の順で決める。有休Fも8時間として含める。\n・夜勤を先に組み、日中は勤務可能な職員が少ない日からC・Bの必要人数を埋め、残りはBで時間目安に近づける。\n・60通りの候補から不足や違反が少ない案を選ぶ。全条件の充足・最適解を保証しない。\n・利用者の開始日・終了日・曜日別の通い／泊まり／訪問予定を日別人数に表示する。人数から必要職員数への自動換算は未接続。\n\n【8時間換算・画面の判定ルール】\n・対象はB・C・D・d・G・Iのみ。1人ずつ勤務時間÷8を小数第1位まで残し、第2位以降を切り捨てて合計する。\n・8時間＝1.0、6時間＝0.7、7時間＝0.8。合計7.0以上で施設基準クリア、6.0〜6.9は青、6.0未満は赤。\n・A・E・F・/B・/C・空欄はこの合計に含めない。\n・7.0未満は警告し、候補比較でも評価するが、必ず7.0以上にできる保証はない。法定配置の適合判定ではない。\n\n【勤務記号・現在の登録時間】\nA：7:00〜16:30（休憩未確認、実働時間未設定）\nB：8:30〜17:30（8時間）\nC：10:30〜19:30（8時間）\nD：16:30〜翌10:30（Dに8時間、翌日dに8時間）\nd：夜勤明け（8時間）\nE：休日（0時間）\nF：有休（時間目安には8時間算入）\nG：9:00〜15:00（6時間）\nI：9:00〜17:00（7時間）\n/B：13:30〜17:30（4時間）\n/C：15:30〜19:30（4時間）\n\n【画像の観察結果・参考情報（自動適用しない）】\n・夜勤：毎日Dが1人、dが1人。\n・夜勤の並び：月内で確認できる382件すべてD→翌日d。\n・夜勤明け：d→Eが345件、残り37件は空欄。直後に別勤務なし。\n・B勤務：395日すべて1人以上。2〜4人の日が約84%。\n・C勤務：395日すべて1人以上。376日（約95%）はちょうど2人。\n・夜勤担当：すべて介護職員。管理者・計画作成担当者・看護職員には夜勤なし。\n・常勤時間：月160・168・176時間が中心。\n・休日数：常勤者はEが平均約9日／月。\n・連続勤務：月内最大6日。ほとんどが4日以内。\n・日曜日：平日より日中配置が少ない。\n・非常勤：G・I・半日勤務などで日中の不足を補う。\n※上記は提供画像の観察結果であり、必須条件・法定基準ではない。初期のB2人・C2人・D1人、連勤上限5日・休日目安9日は試作版の仮設定。\n\n【未対応・担当者による確認が必要】\n・任意の文章をAIが解釈して全条件を自動適用する機能は未接続。先頭の5項目だけ「月の作成条件に反映」で適用する。それ以外は共有・確認用のメモ。\n・毎日Dとdをちょうど1人に制限する機能は未対応（Dは最低人数、dは夜勤の連続配置による）。\n・職種だけで夜勤を制限する機能は未対応。職員の「夜勤：不可」で設定する。\n・日曜の日中減員は自動適用しない。必要なら日別の必要人数で設定する。\n・G・I・半日勤務・Aの自動割当は未対応。手動で入力し、必要なら固定する。\n・休日目安は時間目安の算出に使うもので、休日数ちょうどの保証ではない。勤務時間ちょうど・夜勤回数の完全な均等化も保証しない。\n・月をまたぐ連続勤務の完全な判定、資格別配置、法定配置、利用人数に応じた必要職員数の自動判定は未対応。\n\n【追加の条件メモ（自動適用しない）】\n";}
function parse(text){
 const rules={},errors=[],seen=new Set();let inSettings=false,found=false;
 String(text).normalize('NFKC').split(/\r?\n/).forEach((raw,i)=>{
  const line=raw.trim();if(!line)return;
  if(line==='【自動反映する設定】'){if(found)errors.push('設定の見出しが重複しています。');found=true;inSettings=true;return;}
  if(/^【.*】$/.test(line)){inSettings=false;return;}if(!inSettings)return;
  const match=line.match(/^(Bの最低人数|Cの最低人数|Dの最低人数|連続勤務の上限|休日の目安)\s*:\s*(\d+)\s*(人|日)$/);
  if(!match){errors.push((i+1)+'行目：指定の「項目名：数値＋人／日」の形式にしてください。');return;}
  const field=fields.find(f=>f[1]===match[1]),[key,,min]=field,value=Number(match[2]),unit=['maxRun','off'].includes(key)?'日':'人';
  if(seen.has(key))errors.push(match[1]+'が重複しています。');seen.add(key);
  if(value<min||value>31||match[3]!==unit)errors.push(match[1]+'は'+min+'〜31'+unit+'で指定してください。');
  rules[key]=value;
 });
 if(!found)errors.push('【自動反映する設定】の見出しが必要です。');
 for(const [key,label]of fields)if(!seen.has(key))errors.push(label+'がありません。');
 return {rules,errors};
}
root.ShiftConditions={fields,settings,template,parse};if(typeof module!=='undefined')module.exports=root.ShiftConditions;
})(typeof window!=='undefined'?window:globalThis);
